 j=c.document;j["heads"][0]["key"]="voltage.0.REL.offset";reject(j);j=c.document;j["heads"][0]["selector_offset"]=0;reject(j);j=c.document;j["heads"][0]["row_offset"]=0;reject(j);j=c.document;j["heads"][0]["index"]=2;reject(j);j=c.document;j["heads"][0]["next_index"]=3;reject(j);j=c.document;j["heads"][0]["index"]=6.0;reject(j);j=c.document;j["heads"][0]["variable"]=255;reject(j);j=c.document;j["values"]["voltage.0.OV.offset"]=uint64_t(UINT32_MAX);reject(j);j=c.document;j["requests"].push_back(j["requests"][0]);reject(j);j=c.document;j["slot"]="0000:04:00.00";reject(j);
 j=c.document;j["before_equations"]["info_hex"]="00";reject(j);j=c.document;auto h=j["before_equations"]["info_hex"].get<std::string>();h[0]='A';j["before_equations"]["info_hex"]=h;reject(j);j=c.document;h=j["before_equations"]["control_hex"].get<std::string>();h[8]='0';j["before_equations"]["control_hex"]=h;reject(j);
 auto foreign=c.target;foreign.handle=0;refused([&]{parse_voltage_scaffold_receipt(bytes,foreign,c.windows);},"No fabricated missing current handle");foreign=c.target;foreign.subsystem_id^=1;refused([&]{parse_voltage_scaffold_receipt(bytes,foreign,c.windows);},"Wrong fresh target refused");
 auto duplicate=bytes;const auto at=duplicate.find("\"stable_reads\":2");duplicate.insert(at,"\"stable_reads\":2,");refused([&]{parse_voltage_scaffold_receipt(duplicate,c.target,c.windows);},"Nested duplicate JSON key refused");refused([&]{parse_voltage_scaffold_receipt(bytes.substr(0,bytes.size()-1),c.target,c.windows);},"Truncated JSON refused");refused([&]{parse_voltage_scaffold_receipt(std::string(voltage_scaffold_receipt_max_bytes+1,' '),c.target,c.windows);},"Oversized JSON refused");auto deep=std::string("{\"padding\":")+std::string(34,'[')+"0"+std::string(34,']')+"}";bool depth_rejected=false;try{parse_voltage_scaffold_receipt(deep,c.target,c.windows);}catch(const std::exception& e){depth_rejected=std::string(e.what()).find("nesting")!=std::string::npos;}check(depth_rejected,"Valid deeply nested JSON stopped by depth bound before schema traversal");refused([&]{parse_voltage_scaffold_receipt("{\"schema\":1e9999}",c.target,c.windows);},"Overflow JSON number refused");auto malformed=bytes;malformed.insert(malformed.find(c.windows.instance_id.substr(0,3)),1,static_cast<char>(0xff));refused([&]{parse_voltage_scaffold_receipt(malformed,c.target,c.windows);},"Invalid UTF8 refused");
